 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A separator is a straight run of 5s; its adjacent edge carries a
    # one-dimensional motif which is extended across the bounded panel.
    # Horizontal separators: source motif runs down the first cell beyond
    # the separator, then each source value is copied across the panel row.
    horiz = [r for r in range(h) if sum(v == 5 for v in g[r]) >= 3]
    vert = [c for c in range(w) if sum(g[r][c] == 5 for r in range(h)) >= 3]
    for r in horiz:
        cols = [c for c, v in enumerate(g[r]) if v == 5]
        lo, hi = min(cols), max(cols)
        # Locate adjoining vertical payload immediately below the bar.
        for c in range(lo, hi + 1):
            vals = [g[rr][c] for rr in range(r + 1, h) if g[rr][c] != 0 and g[rr][c] != 5]
            if vals:
                seq = [g[rr][c] for rr in range(r + 1, h)]
                for rr in range(r + 1, h):
                    if g[rr][c] not in (0, 5):
                        for cc in range(lo, hi + 1):
                            if g[rr][cc] == 0: g[rr][cc] = g[rr][c]
                break
    for c in vert:
        rows = [r for r in range(h) if g[r][c] == 5]
        lo, hi = min(rows), max(rows)
        # Motif immediately to the right, possibly multiple rows tall.
        motif = []
        for r in range(hi, max(-1, hi-3), -1):
            vals = []
            for cc in range(c + 1, w):
                if g[r][cc] != 0 and g[r][cc] != 5: vals.append(g[r][cc])
                elif vals: break
            if vals: motif.append((r, vals))
            elif motif: break
        motif.reverse()
        if not motif:
            # One-line source may occur at the final divider row.
            for r in range(h-1, -1, -1):
                vals=[]
                for cc in range(c+1,w):
                    if g[r][cc] not in (0,5): vals.append(g[r][cc])
                    elif vals: break
                if vals:
                    motif=[(r,vals)]; break
        if motif:
            base = motif[0][0]
            period = len(motif)
            for r in range(lo, hi+1):
                if r in [x[0] for x in motif]: continue
                vals = motif[(r-base) % period][1]
                for j, value in enumerate(vals):
                    cc = c + 1 + j
                    if cc < w and g[r][cc] == 0: g[r][cc] = value
    return g

