 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Find continuous 5-valued divider lines.
    hbars=[r for r in range(h) if sum(v==5 for v in g[r])>=3]
    vbars=[c for c in range(w) if sum(g[r][c]==5 for r in range(h))>=3]
    # Extend color sequences beside horizontal dividers across their panel width.
    for r in hbars:
        cols=[c for c,v in enumerate(g[r]) if v==5]
        runs=[]
        for c in cols:
            if not runs or c>runs[-1][-1]+1:runs.append([c])
            else:runs[-1].append(c)
        for run in runs:
            lo,hi=run[0],run[-1]
            # Find a payload immediately beneath the bar, then copy its
            # scalar along that row, bounded by this bar segment.
            for c in range(lo,hi+1):
                if g[r+1][c] not in (0,5):
                    for rr in range(r+1,h):
                        if g[rr][c]==5: break
                        if g[rr][c] not in (0,5):
                            val=g[rr][c]
                            for cc in range(lo,hi+1):
                                if g[rr][cc]==0:g[rr][cc]=val
                    break
    # Extend a motif from the edge adjacent to a vertical divider across rows.
    for c in vbars:
        rows=[r for r in range(h) if g[r][c]==5]
        lo,hi=min(rows),max(rows)
        # Identify right-side colored row motifs in the panel and repeat the
        # observed motif cycle throughout the divider's vertical span.
        samples=[]
        for r in range(lo,hi+1):
            vals=[]
            for cc in range(c+1,w):
                if g[r][cc] not in (0,5): vals.append(g[r][cc])
                elif vals: break
            if vals:samples.append((r,vals))
        if samples:
            # If source is at the bottom, its row sequence repeats upward;
            # if at top, repeat downward.
            period=len(samples)
            anchor=samples[0][0]
            table={r:vals for r,vals in samples}
            for r in range(lo,hi+1):
                vals=table.get(r, samples[(r-anchor)%period][1])
                for j,val in enumerate(vals):
                    cc=c+1+j
                    if cc<w and g[r][cc]==0:g[r][cc]=val
    return g

